          "checkScript": "\nuser_code = globals().get(\"__user_code__\", \"\")\nassert \"lambda\" in user_code, \"В этом задании ОБЯЗАТЕЛЬНО нужно использовать lambda! / Бул тапшырмада СӨЗСҮЗ lambda колдонуу керек!\"\nassert \"multiply_by_two\" in globals() and callable(globals()[\"multiply_by_two\"]), \"Переменная multiply_by_two не найдена или не является функцией! / multiply_by_two өзгөрмөсү табылган жок же функция эмес!\"\n\nf = globals()[\"multiply_by_two\"]\nassert f(5) == 10, f\"Для x=5 ожидалось 10, получено: {f(5)}\"\nassert f(0) == 0, f\"Для x=0 ожидалось 0\"\nassert f(-3) == -6, f\"Для x=-3 ожидалось -6\"\nassert f(12) == 24, f\"Для x=12 ожидалось 24\"\n",
